('f22','TEC-26-F01',0,$j${"date":"2026-11-11","text":"上一版本产品开发说明书已经提交并且界面设计已经完成；本周重新优化设计中，预计下周可以与系统组对接需求","by":"赵栋Alex"}$j$::jsonb),
