-- Incremental data refresh from the 2026-11-12 progress sheet (generated; see docs/data-refresh-sync-2026-11-12.md).
--
-- WHAT IT DOES (and nothing else): for the imported projects / follow-ups (ids p0..p253, f0..f39) it applies the
-- changes the new sheet brought: owner, executors, planned end date, name (2 renamed), status, extension dates,
-- new progress records; and it adds the new projects / follow-up (ids p254.., f40).
-- WHAT IT NEVER DOES: delete anything; touch requests, approvals, records (to-dos, issues, meetings, ALSA), mail,
-- people, or anything on projects created on the platform; overwrite a value somebody changed on the platform after the
-- import (a field is only changed while the database still holds the value the old sheet had); touch two-week updates
-- (new progress records are only appended; existing and platform-written ones stay).
-- It is one transaction and can be run again (a second run changes nothing).
-- The last result set lists every change that was NOT applied because the platform value had been changed meanwhile.
--
-- OPTIONAL, recommended: the app's member sync (next PMO login) mails "[Assigned]" to people newly named as owner or
-- executor. To avoid that, run the next line first and the second one after the first PMO login:
--   insert into public.app_state(key,data) values ('flags','{"mute_mail":"true"}') on conflict (key) do update set data = public.app_state.data || '{"mute_mail":"true"}';
--   update public.app_state set data = data || '{"mute_mail":"false"}' where key = 'flags';

begin;

do $$
begin
  if (select count(*) from public.projects where id ~ '^[pf][0-9]+$') < 200 then
    raise exception 'The database does not hold the imported projects (expected ids p0.., f0..). Nothing was changed.';
  end if;
end $$;

drop table if exists _dr_chg, _dr_st, _dr_ext, _dr_upd, _dr_new, _dr_report;
create temp table _dr_chg (id text, code text, field text, old jsonb, new jsonb);
create temp table _dr_st  (id text, code text, kind text, old_status text, new_status text, new_orig text, closed_at text, was_closed boolean);
create temp table _dr_ext (id text, code text, add jsonb);
create temp table _dr_upd (id text, code text, n int, upd jsonb);
create temp table _dr_new (id text, code text);

create or replace function pg_temp.append_missing(base jsonb, add jsonb) returns jsonb language sql immutable as $f$
  select coalesce(base,'[]'::jsonb) || coalesce((select jsonb_agg(x) from jsonb_array_elements(add) x where not (coalesce(base,'[]'::jsonb) @> jsonb_build_array(x))),'[]'::jsonb)
$f$;

-- 1. field changes (owner, executors, planned end, name): 31 values on 26 items

-- 2. status changes: 17 items

-- 3. extension dates to add: 11 items

-- 4. new progress records to append: 98

-- apply 1: only while the database still holds the value the old sheet had
with t as (
  select c.id, jsonb_object_agg(c.field, c.new) as patch
    from _dr_chg c join public.projects p on p.id = c.id
   where coalesce(p.data -> c.field, 'null'::jsonb) = coalesce(c.old, 'null'::jsonb)
   group by c.id)
update public.projects p
   set data = p.data || t.patch,
       name = coalesce(t.patch ->> 'name', p.name)
  from t where p.id = t.id;

-- apply 2: status (closing also stamps the close date and marks the milestones done; reopening removes the close date)
update public.projects p
   set status = s.new_status,
       data = case
         when s.kind = 'follow' then p.data || jsonb_build_object('status', s.new_status, 'origStatus', s.new_orig)
         when s.new_status = 'closed' then p.data || jsonb_build_object('status', s.new_status, 'origStatus', s.new_orig, 'closedAt', s.closed_at,
              'milestones', coalesce((select jsonb_agg(m || '{"done":true}'::jsonb) from jsonb_array_elements(coalesce(p.data -> 'milestones', '[]'::jsonb)) m), '[]'::jsonb))
         else (p.data - 'closedAt') || jsonb_build_object('status', s.new_status, 'origStatus', s.new_orig)
       end
  from _dr_st s
 where p.id = s.id and p.status = s.old_status and p.data ->> 'status' = s.old_status;

-- apply 3: extension dates that are not there yet
update public.projects p
   set data = jsonb_set(p.data, '{exts}', pg_temp.append_missing(p.data -> 'exts', e.add))
  from _dr_ext e
 where p.id = e.id and pg_temp.append_missing(p.data -> 'exts', e.add) is distinct from coalesce(p.data -> 'exts', '[]'::jsonb);

-- apply 4: new progress records, appended after everything that is already there (skipped when the same text exists)
with fresh as (
  select u.id, u.n, u.upd
    from _dr_upd u join public.projects p on p.id = u.id
   where not exists (
     select 1 from jsonb_array_elements(coalesce(p.data -> 'updates', '[]'::jsonb)) x
      where left(btrim(regexp_replace(coalesce(x ->> 'text', ''), '\s+', ' ', 'g')), 60) = left(btrim(regexp_replace(coalesce(u.upd ->> 'text', ''), '\s+', ' ', 'g')), 60))),
agg as (select id, jsonb_agg(upd order by n) as add from fresh group by id)
update public.projects p
   set data = jsonb_set(p.data, '{updates}', coalesce(p.data -> 'updates', '[]'::jsonb) || a.add)
  from agg a where p.id = a.id;

-- 5. new projects / follow-up: 8 (an existing id or code is left alone)
on conflict do nothing;


-- report: everything that was not applied
create temp table _dr_report as
  select c.code, c.field as what, (p.data -> c.field)::text as in_database, c.new::text as from_sheet, 'kept: changed on the platform after the import' as note
    from _dr_chg c join public.projects p on p.id = c.id
   where coalesce(p.data -> c.field, 'null'::jsonb) is distinct from coalesce(c.new, 'null'::jsonb)
  union all
  select s.code, 'status', p.status, s.new_status, 'kept: changed on the platform after the import'
    from _dr_st s join public.projects p on p.id = s.id
   where p.status is distinct from s.new_status
  union all
  select n.code, 'new item', null, null, 'not added: the id or code already exists in the database'
    from _dr_new n where not exists (select 1 from public.projects p where p.id = n.id and p.code = n.code);

commit;

select * from (select 'nothing was left out: every change was applied' as code, null as what, null as in_database, null as from_sheet, null as note
                where not exists (select 1 from _dr_report)
               union all select * from _dr_report) r
 order by code;
